-- Modify "licenses" table
ALTER TABLE "licenses" ADD CONSTRAINT "licenses_ent_limit_ints" CHECK (NOT jsonb_path_exists(entitlements, 'strict $."limits".*?(@.string() like_regex "[.eE]")'::jsonpath)), ADD CONSTRAINT "licenses_ent_limit_keys" CHECK (NOT jsonb_path_exists(entitlements, 'strict $."limits".keyvalue()?(!(@."key" like_regex "^[a-z][a-z0-9]*(_[a-z0-9]+)*$"))'::jsonpath)), ADD CONSTRAINT "licenses_issued_has_expiry" CHECK (((expiry_basis)::text <> 'from_issue'::text) OR (num_nonnulls(duration_months, duration_seconds) = 0) OR (expires_at IS NOT NULL)), ADD CONSTRAINT "licenses_site_no_activation_max" CHECK (((bind_type)::text <> 'none'::text) OR (max_activations IS NULL)), ADD CONSTRAINT "licenses_site_starts_at_issue" CHECK (((bind_type)::text <> 'none'::text) OR ((expiry_basis)::text <> 'from_first_activation'::text));
-- Modify "plans" table
ALTER TABLE "plans" ADD CONSTRAINT "plans_site_no_activation_max" CHECK (((bind_type)::text <> 'none'::text) OR (max_activations IS NULL)), ADD CONSTRAINT "plans_site_starts_at_issue" CHECK (((bind_type)::text <> 'none'::text) OR ((expiry_basis)::text <> 'from_first_activation'::text));
